import{_ as a,c as l,o as i,a0 as n}from"./chunks/framework.C1J0Vcxi.js";const h=JSON.parse('{"title":"项目计划 — 2026年5月至8月","description":"","frontmatter":{},"headers":[],"relativePath":"项目计划/项目计划-20260511.md","filePath":"项目计划/项目计划-20260511.md"}'),o={name:"项目计划/项目计划-20260511.md"};function s(c,e,t,d,r,p){return i(),l("div",null,[...e[0]||(e[0]=[n(`<h1 id="项目计划-—-2026年5月至8月" tabindex="-1">项目计划 — 2026年5月至8月 <a class="header-anchor" href="#项目计划-—-2026年5月至8月" aria-label="Permalink to &quot;项目计划 — 2026年5月至8月&quot;">​</a></h1><h2 id="一、当前状态" tabindex="-1">一、当前状态 <a class="header-anchor" href="#一、当前状态" aria-label="Permalink to &quot;一、当前状态&quot;">​</a></h2><h3 id="_1-1-任务清单" tabindex="-1">1.1 任务清单 <a class="header-anchor" href="#_1-1-任务清单" aria-label="Permalink to &quot;1.1 任务清单&quot;">​</a></h3><ul><li>[x] 核心调度器</li><li>[x] PriorityBitmap</li><li>[x] Executor / Spawner</li><li>[x] 过程宏 (<code>#[task]</code> <code>#[main]</code> <code>#[interrupt]</code>)</li><li>[x] 平台抽象 (QEMU virt)</li><li>[x] Timer / TimerQueue</li><li>[x] 集成测试 (12 个)</li><li>[ ] 同步原语 (Mutex / Semaphore / Channel / EventGroup)</li><li>[ ] JoinHandle / CancellationToken</li><li>[ ] 周期定时器 / 超时包装</li><li>[ ] 多平台 (ARM / VF2)</li></ul><h3 id="_1-2-与-embassy-preempt-的关系" tabindex="-1">1.2 与 embassy_preempt 的关系 <a class="header-anchor" href="#_1-2-与-embassy-preempt-的关系" aria-label="Permalink to &quot;1.2 与 embassy_preempt 的关系&quot;">​</a></h3><p>embassy_preempt_VisionFive2 是本项目的前身，已在 VF2 上验证了：</p><ul><li>抢占式调度 + 共享栈的可行性</li><li>AMP 异构多核架构（S7 实时核 + U74 通用核）</li><li>核间通信（IPI + 共享内存）</li></ul><p>rt-async 在此基础上重新设计了调度内核，目标是更简洁的架构和更好的可移植性。</p><hr><h2 id="二、八月目标" tabindex="-1">二、八月目标 <a class="header-anchor" href="#二、八月目标" aria-label="Permalink to &quot;二、八月目标&quot;">​</a></h2><p>一个<strong>可用的实时内核</strong>，具备完整的同步、通信和任务管理能力：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                  ┌──────────────────────────────────┐</span></span>
<span class="line"><span>                  │         应用层 (apps/)            │</span></span>
<span class="line"><span>                  │       Rust async task             │</span></span>
<span class="line"><span>                  ├──────────────────────────────────┤</span></span>
<span class="line"><span>                  │         系统服务层                 │</span></span>
<span class="line"><span>                  │  Mutex / Sem / Channel / EventGrp │</span></span>
<span class="line"><span>                  │  Timer / Timeout / Periodic       │</span></span>
<span class="line"><span>                  │  JoinHandle / CancellationToken   │</span></span>
<span class="line"><span>                  ├──────────────────────────────────┤</span></span>
<span class="line"><span>                  │         调度内核                   │</span></span>
<span class="line"><span>                  │  Spawner + Executor + Bitmap      │</span></span>
<span class="line"><span>                  │  共享栈 + 优先级抢占               │</span></span>
<span class="line"><span>                  ├──────────────────────────────────┤</span></span>
<span class="line"><span>                  │         HAL / 驱动层              │</span></span>
<span class="line"><span>                  │  QEMU virt / JH7110 / ARM Cortex-M│</span></span>
<span class="line"><span>                  └──────────────────────────────────┘</span></span></code></pre></div><hr><h2 id="三、开发计划" tabindex="-1">三、开发计划 <a class="header-anchor" href="#三、开发计划" aria-label="Permalink to &quot;三、开发计划&quot;">​</a></h2><p><strong>原则：每个功能完成后立即补充对应测试，不做集中测试阶段。</strong></p><h3 id="阶段一-同步原语" tabindex="-1">阶段一：同步原语 <a class="header-anchor" href="#阶段一-同步原语" aria-label="Permalink to &quot;阶段一：同步原语&quot;">​</a></h3><p>补齐内核最基本的同步和通信机制。</p><ul><li>[ ] <code>Mutex&lt;T&gt;</code> — 支持优先级继承的异步互斥锁 <ul><li>[ ] <code>MutexGuard</code> RAII 自动释放</li><li>[ ] 等待队列按优先级排序</li><li>[ ] 释放时恢复原始优先级并唤醒等待者</li><li>[ ] 测试：<code>mutex.rs</code></li><li>[ ] 测试：<code>priority_inversion.rs</code>（验证优先级继承）</li></ul></li><li>[ ] <code>Semaphore</code> — 计数信号量 <ul><li>[ ] <code>acquire().await</code> / <code>release(n)</code></li><li>[ ] <code>SemaphorePermit</code> RAII 守卫</li><li>[ ] 测试：<code>semaphore.rs</code></li></ul></li><li>[ ] <code>Channel</code> — MPSC 通道 <ul><li>[ ] intrusive linked list，零堆分配</li><li>[ ] 容量 0 = rendezvous 模式</li><li>[ ] 测试：<code>channel.rs</code></li></ul></li><li>[ ] <code>EventGroup</code> — 32-bit 事件位 <ul><li>[ ] <code>wait(mask, Any|All).await</code> / <code>set(bits)</code></li><li>[ ] 测试：<code>event_group.rs</code></li></ul></li></ul><p>交付物：<code>modules/executor/src/sync/</code></p><hr><h3 id="阶段二-平台扩展" tabindex="-1">阶段二：平台扩展 <a class="header-anchor" href="#阶段二-平台扩展" aria-label="Permalink to &quot;阶段二：平台扩展&quot;">​</a></h3><ul><li>[ ] HAL 层重构 <ul><li>[ ] 拆分 <code>Chip</code> trait 为 <code>Console</code> / <code>Interrupt</code> / <code>Timer</code> / <code>InterruptController</code></li><li>[ ] 新建 <code>modules/hal/</code> + <code>modules/drivers/</code></li><li>[ ] RISC-V 公共层：CLINT / CSR / trap 处理</li><li>[ ] 回归测试：现有 QEMU 测试全部通过</li></ul></li><li>[ ] VisionFive2 (JH7110) 驱动 <ul><li>[ ] CLINT 定时器 + 软件中断</li><li>[ ] UART 控制台</li><li>[ ] GPIO 基本读写</li><li>[ ] PLIC 外部中断</li><li>[ ] 链接脚本 + M-mode 启动代码</li><li>[ ] 测试：VF2 上运行 demo 验证</li></ul></li></ul><hr><h3 id="阶段三-任务与时间管理" tabindex="-1">阶段三：任务与时间管理 <a class="header-anchor" href="#阶段三-任务与时间管理" aria-label="Permalink to &quot;阶段三：任务与时间管理&quot;">​</a></h3><p>完善 task 生命周期和定时器能力。</p><ul><li>[ ] <code>JoinHandle&lt;T&gt;</code> — spawn 返回可 await 的句柄 <ul><li>[ ] <code>TaskStorage</code> 增加 result slot + join waker</li><li>[ ] <code>JoinHandle</code> 实现 <code>Future&lt;Output = T&gt;</code></li><li>[ ] 测试：<code>join_handle.rs</code></li></ul></li><li>[ ] <code>CancellationToken</code> — 协作式任务取消 <ul><li>[ ] <code>cancel()</code> 请求取消（Queued/Waiting 立即生效，Running 等 await 点生效）</li><li>[ ] <code>cancelled().await</code> task 内主动检查</li><li>[ ] <code>TaskInfo</code> 增加 cancel flag</li><li>[ ] 测试：<code>cancel_token.rs</code></li></ul></li><li>[ ] <code>PeriodicTimer</code> — <code>every(duration)</code> 周期触发 <ul><li>[ ] 测试：<code>periodic_timer.rs</code></li></ul></li><li>[ ] <code>with_timeout(dur, future)</code> / <code>with_deadline(instant, future)</code><ul><li>[ ] 测试：<code>timeout.rs</code></li></ul></li><li>[ ] <code>TimerQueue</code> 改进：支持取消已注册定时器</li><li>[ ] <code>Instant</code> / <code>Duration</code> 类型完善</li></ul><p>交付物：<code>modules/futures/src/{cancel, timeout, timer}.rs</code></p><hr>`,28)])])}const m=a(o,[["render",s]]);export{h as __pageData,m as default};
